package glitch

import data.glitch_lib

# Credential-related keywords
credential_keywords := {
    "password", "pwd", "passwd", "secret", "key", "token", "api_key", "apikey",
    "auth_token", "access_key", "secret_key", "private_key", "credential", "credentials",
    "admin", "administrator", "root", "system", "service_account", "default_user",
    "master_user", "bootstrap_user", "connection_string", "dsn", "uri", "url",
    "endpoint", "host", "server", "broker", "database_url", "cert", "certificate",
    "ca_cert", "tls_cert", "ssl_cert", "key_pem", "cert_pem", "signing_key",
    "encryption_key", "bootstrap", "init", "initialize", "setup", "seed", "master_key",
    "enrollment_token", "join_token", "vault_token"
}

# Value attribute names
value_attrs := {"value", "default_value", "initial_value", "string_value", "content", "default"}

# Check if string matches credential keyword pattern
matches_credential_keyword(str) {
    kw := credential_keywords[_]
    regex.match(sprintf("(?i).*%s.*", [kw]), str)
}

# Check if attribute name is credential-related
is_credential_attr_name(name) {
    matches_credential_keyword(name)
}

# Check for high-entropy patterns (base64, hex, PEM, UUID-like)
has_secret_pattern(str) {
    # Base64 pattern (40+ chars)
    regex.match("^[A-Za-z0-9+/]{40,}={0,2}$", str)
} else {
    # Hex pattern (32+ chars)
    regex.match("^[0-9a-fA-F]{32,}$", str)
} else {
    # PEM header pattern
    regex.match("(?i).*-----BEGIN", str)
} else {
    # UUID-like pattern
    regex.match("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", str)
}

# Check for URL with embedded credentials
has_embedded_credentials(str) {
    regex.match("^[A-Za-z]+://[^/]+:[^/]+@[^/]+", str)
}

# Extract string value from expression
get_string_value(val) = s {
    val.ir_type == "String"
    s := val.value
} else = s {
    val.ir_type == "VariableReference"
    s := val.value
}

# Check if value contains literal secret
contains_literal_secret(val) {
    s := get_string_value(val)
    has_secret_pattern(s)
} else {
    s := get_string_value(val)
    has_embedded_credentials(s)
} else {
    # Check nested structures recursively
    walk(val, [_, n])
    n.ir_type == "String"
    has_secret_pattern(n.value)
} else {
    walk(val, [_, n])
    n.ir_type == "String"
    has_embedded_credentials(n.value)
}

# Check Hash for credential entries
hash_has_credential(hash_val) {
    some key_expr, val_expr
    hash_val.value[key_expr] = val_expr

    key_str := get_string_value(key_expr)
    is_credential_attr_name(key_str)

    # High entropy or literal value (not a reference)
    val_expr.ir_type != "VariableReference"
    contains_literal_secret(val_expr)
}

# Check Array for credential patterns
array_has_credential(arr_val) {
    some elem
    arr_val.value[_] = elem

    # Check if element is a key-value pair in a hash
    elem.ir_type == "Hash"
    hash_has_credential(elem)
} else {
    some elem
    arr_val.value[_] = elem
    elem.ir_type == "String"
    has_secret_pattern(elem.value)
}

# Check if KeyValue (Variable or Attribute) contains hardcoded credential
has_hardcoded_credential(kv) {
    is_credential_attr_name(kv.name)
    contains_literal_secret(kv.value)
}

# Check Variable for hardcoded credentials
variable_has_credential(var) {
    has_hardcoded_credential(var)
}

# Check Attribute for hardcoded credentials
attribute_has_credential(attr) {
    has_hardcoded_credential(attr)
} else {
    # Check value_attrs pattern with credential content
    value_attrs[attr.name]
    contains_literal_secret(attr.value)
} else {
    # Check nested Hash in attribute value
    attr.value.ir_type == "Hash"
    hash_has_credential(attr.value)
} else {
    # Check nested Array in attribute value
    attr.value.ir_type == "Array"
    array_has_credential(attr.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables in UnitBlock
    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    variable_has_credential(var)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in AtomicUnits
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]
    attribute_has_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes directly in UnitBlock
    attr := parent.attributes[_]
    attribute_has_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

package glitch

import data.glitch_lib

# Credential-related keywords (prefix/suffix/infix matching)
credential_keywords := {
    "password", "pwd", "passwd", "secret", "key", "token", "api_key", "apikey",
    "auth_token", "access_key", "secret_key", "private_key", "credential", "credentials",
    "master_password", "admin_password", "root_password", "sha512_password",
    "bootstrap", "init", "initialize", "setup", "seed", "master_key",
    "enrollment_token", "join_token", "vault_token"
}

# Check if string contains credential keyword
matches_credential_keyword(str) {
    kw := credential_keywords[_]
    regex.match(sprintf("(?i).*%s.*", [kw]), str)
}

# Base64 pattern (20+ chars, allowing embedded credentials)
is_base64_candidate(str) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", str)
}

# Detect password hash patterns (SHA512, MD5, etc.)
is_password_hash(str) {
    regex.match("^\\$[0-9a-zA-Z]+\\$", str)
}

# Any string that looks like a credential value (not a simple word)
is_credential_value(str) {
    is_base64_candidate(str)
} else {
    is_password_hash(str)
} else {
    # High complexity string (not just lowercase word)
    regex.match(".*[^a-z].*", str)
    count(str) > 6
}

# Check if KeyValue name contains credential keyword
has_credential_name(kv) {
    matches_credential_keyword(kv.name)
}

# Recursively find hash entries with credential keys and literal values
find_hash_credential(val) = result {
    val.ir_type == "Hash"
    some key_expr, v
    val.value[key_expr] = v

    key_str := get_string(key_expr)
    matches_credential_keyword(key_str)

    # Value should be a literal (not a reference)
    v.ir_type == "String"
    value_str := v.value
    is_credential_value(value_str)

    result := {
        "key": key_str,
        "value": value_str,
        "element": v
    }
}

# Get string value from expression
get_string(val) = s {
    val.ir_type == "String"
    s := val.value
} else = s {
    val.ir_type == "VariableReference"
    s := val.value
}

# Recursively check nested structures for credentials via walk
deep_credential_detection(node, original) = result {
    walk(node, [_, n])
    n.ir_type == "Hash"
    some key_expr, v
    n.value[key_expr] = v

    key_str := get_string(key_expr)
    matches_credential_keyword(key_str)

    v.ir_type == "String"
    value_str := v.value
    is_credential_value(value_str)

    result := {
        "key": key_str,
        "value": value_str,
        "element": v,
        "container": original
    }
}

# Variable detection: direct or deep nested
detect_variable_credential(var) = result {
    # Direct string value with credential name
    var.value.ir_type == "String"
    has_credential_name(var)
    value_str := var.value.value
    is_credential_value(value_str)

    result := {
        "key": var.name,
        "value": value_str,
        "element": var
    }
} else = result {
    # Nested hash detection via walk
    deep_cred := deep_credential_detection(var.value, var)
    result := {
        "key": deep_cred.key,
        "value": deep_cred.value,
        "element": deep_cred.element,
        "container": var
    }
}

# Attribute detection: direct or deep nested
detect_attribute_credential(attr) = result {
    # Direct string value with credential name
    attr.value.ir_type == "String"
    has_credential_name(attr)
    value_str := attr.value.value
    is_credential_value(value_str)

    result := {
        "key": attr.name,
        "value": value_str,
        "element": attr
    }
} else = result {
    # Nested hash detection via walk
    deep_cred := deep_credential_detection(attr.value, attr)
    result := {
        "key": deep_cred.key,
        "value": deep_cred.value,
        "element": deep_cred.element,
        "container": attr
    }
}

# Main rule for variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    cred := detect_variable_credential(var)

    result := {
        "type": "sec_hard_secr",
        "element": cred.element,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

# Main rule for attributes in atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    cred := detect_attribute_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": cred.element,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

# Main rule for direct UnitBlock attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attr := parent.attributes[_]

    cred := detect_attribute_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": cred.element,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Credentials are hard-coded in the configuration, which may allow attackers to bypass authentication and gain unauthorized access. (CWE-798)"
    }
}

