package glitch

import data.glitch_lib

# Credential-related keywords - expanded to match more patterns
credential_terms := {"password", "pwd", "passwd", "secret", "token", "api_key", "apikey", "auth_token", "access_key", "secret_key", "private_key", "credential", "credentials", "passphrase", "login_passwd", "key"}

# LDAP attribute patterns that are configuration metadata, not credentials
ldap_metadata_patterns := {"_tree_dn$", "_objectclass$", "_attribute$", "_desc_attribute$", "_name_attribute$", "_id_attribute$", "_member_attribute$", "user_enabled", "user_allow_", "group_allow_", "tls_cacertfile"}

# System account names that are not secrets
system_accounts := {"root", "administrator", "admin", "nobody", "daemon", "bin", "sys", "sync", "games", "man", "lp", "mail", "news", "uucp", "proxy", "www-data", "backup", "list", "irc", "gnats"}

is_credential_term(name) {
    term := credential_terms[_]
    # Match at word boundaries (start, underscore, dot, bracket) allowing dots for Chef nested names
    regex.match(sprintf("(?i)(^|_|\\.|\\[)(%s)([^a-zA-Z0-9_]|$)", [term]), name)
}

# Check if name is LDAP metadata (not a credential)
is_ldap_metadata(name) {
    pattern := ldap_metadata_patterns[_]
    regex.match(name, pattern)
}

# Check if value is a system account name (not a credential)
is_system_account(value) {
    v_lower := lower(value)
    v_lower == system_accounts[_]
}

# Check if value looks like a file path
is_file_path(value) {
    regex.match("^[\\./~]?[a-zA-Z0-9_./~-]+/[a-zA-Z0-9_.~-]+$", value)
}

# Check if value is a simple boolean-like string
is_boolean_string(value) {
    v_lower := lower(value)
    v_lower == "true"
} else {
    v_lower := lower(value)
    v_lower == "false"
}

# Check if value has credential-like characteristics - more permissive
has_credential_characteristics(value) {
    # Has mixed case and special chars or numbers
    regex.match("[A-Z]", value)
    regex.match("[a-z]", value)
    regex.match("[0-9!@#$%^&*]", value)
} else {
    # Or is base64-like (allow shorter length for encoded passwords)
    regex.match("^[A-Za-z0-9+/]{10,}={0,2}$", value)
} else {
    # Or is a password hash (sha256, sha512, bcrypt, etc.)
    regex.match("^\\$[0-9a-z]+\\$", value)
} else {
    # Or is long and has some complexity
    count(value) >= 8
    regex.match("[^a-z]", value)
    not regex.match("^[a-z]+$", value)
} else {
    # Simple passwords that are long enough and not just lowercase
    count(value) >= 8
    not is_simple_identifier(value)
}

# Check if value is a simple identifier/word (not a credential)
is_simple_identifier(value) {
    regex.match("^[a-z]+$", value)
    count(value) < 15
}

# Extract string value from expression
get_string_value(expr) = s {
    expr.ir_type == "String"
    s = expr.value
} else = s {
    expr.ir_type == "VariableReference"
    s = expr.value
} else = s {
    # Handle KeyValue key extraction
    expr.ir_type == "KeyValue"
    s = get_string_value(expr.key)
}

# Recursively find all KeyValue nodes with credential keys and string values in a node
find_credential_kvs(node) = results {
    results := {kv |
        walk(node, [_, n])
        n.ir_type == "KeyValue"
        key_str := get_string_value(n.key)
        key_str != null
        is_credential_term(key_str)
        not is_ldap_metadata(key_str)
        n.value.ir_type == "String"
        val := n.value.value
        val != ""
        not is_boolean_string(val)
        kv := {"key": key_str, "value": val, "element": n}
    }
}

# Find credentials in nested hash structures by walking into Hash values
find_nested_credential_kvs(node) = results {
    results := {kv |
        walk(node, [_, n])
        n.ir_type == "Hash"
        some i
        entry := n.value[i]
        entry.ir_type == "KeyValue"
        key_str := get_string_value(entry.key)
        key_str != null
        is_credential_term(key_str)
        not is_ldap_metadata(key_str)
        entry.value.ir_type == "String"
        val := entry.value.value
        val != ""
        not is_boolean_string(val)
        kv := {"key": key_str, "value": val, "element": entry}
    }
}

# Check if a value should be reported as credential
is_reportable_credential(val) {
    has_credential_characteristics(val)
    not is_system_account(val)
    not is_file_path(val)
}

