}

is_ldap_attr_value(val) {
    lower_val := lower(val)
    ldap_vals := {"uid", "cn", "dc", "ou", "o", "mail", "description", "member", "groupofnames", "person", "nsaccountlock", "true", "false"}
    lower_val == ldap_vals[_]
} else {
    regex.match("^[^@]+@[^@]+\\.[^@]+$", val)
}

is_boolean_string(val) {
    lower(val) == "true"
} else {
    lower(val) == "false"
}

is_simple_path(val) {
    regex.match("^(/[^/ ]+)+\\.?[a-z]*$", val)
}

